 ok(Tactical27.attention(.9,100,5)&&!Tactical27.attention(-.9,100,5)&&!Tactical27.attention(.9,100,25),"hide response requires player turning toward recent shooter");ok(Tactical27.smooth(0)==0&&Tactical27.smooth(1)==1&&Tactical27.smooth(.5)==.5,"slide easing has fixed end points");long now=System.nanoTime();ok(Motion27.weight(now,now,now+650000000L)==0,"slide animation starts at neutral pose");ok(Motion27.weight(now+200000000L,now,now+650000000L)==1,"slide reaches full grounded pose");ok(Motion27.weight(now+650000000L,now,now+650000000L)==0,"slide restores base model without residual transform");
 var passive=MotionChecks26.actor(w,0,203);ok(!Threat27.acquire(passive,CalmBrain.state(passive),500,false),"passive disposition left to existing social rules");
