 var bottle=new ItemStack("minecraft:potion",1);bottle.set(net.minecraft.core.component.DataComponents.POTION_CONTENTS,new Potion(true));fresh.bag.add(bottle);fresh.tag.putLong("npc27_water_at",1240);state.serviceAt=0;Tactical27.service(fresh,state,1300,true);Tactical27.service(fresh,state,1310,true);Tactical27.service(fresh,state,1340,true);ok(fresh.bag.stream().noneMatch(i->i.id.equals("minecraft:potion"))&&fresh.bag.stream().anyMatch(i->i.id.equals("minecraft:glass_bottle")),"drinking consumes water and keeps empty bottle");ok(fresh.sounds>0,"consumption plays eat/drink sounds while gesturing");var poison=new ItemStack("minecraft:potion",1);poison.set(net.minecraft.core.component.DataComponents.POTION_CONTENTS,new Potion(false));ok(Tactical27.kind(poison).isEmpty(),"non-water potion never used as drinking water");
